   720→  padding: 16px 20px 24px;
   721→  display: flex;
   722→  justify-content: flex-end;
   723→}
   724→
   725→/* ===== Keyframes ===== */
   726→@keyframes fade-in {
   727→  from { opacity: 0; }
   728→  to   { opacity: 1; }
   729→}
   730→
   731→@keyframes blink {
   732→  0%, 100% { opacity: 1; }
   733→  50%       { opacity: 0.4; }
   734→}
   735→
   736→@keyframes spin {
   737→  from { transform: rotate(0deg); }
   738→  to   { transform: rotate(360deg); }
   739→}
   740→
   741→/* ===== Safe area for notch phones ===== */
   742→@supports (padding: env(safe-area-inset-bottom)) {
   743→  .header {
   744→    padding-top: calc(16px + env(safe-area-inset-top));
   745→    padding-left: calc(20px + env(safe-area-inset-left));
   746→    padding-right: calc(20px + env(safe-area-inset-right));
   747→  }
   748→
   749→  .mic-section {
   750→    padding-bottom: calc(36px + env(safe-area-inset-bottom));
   751→  }
   752→}
   753→
   754→/* ===== Wake word indicator ===== */
   755→.wake-dot {
   756→  width: 8px;
   757→  height: 8px;
   758→  border-radius: 50%;
   759→  background: #34c759;
   760→  box-shadow: 0 0 6px rgba(52, 199, 89, 0.55);
   761→  flex-shrink: 0;
   762→  animation: wake-pulse 2s ease-in-out infinite;
   763→}
   764→
   765→@keyframes wake-pulse {
   766→  0%, 100% { opacity: 1; transform: scale(1); }
   767→  50%       { opacity: 0.5; transform: scale(0.8); }
   768→}
   769→
   770→/* ===== Hands-free toggle in settings ===== */
   771→.toggle-label {
   772→  display: flex;
   773→  align-items: center;
   774→  justify-content: space-between;
   775→  font-size: 0.85rem;
   776→  color: var(--text-muted);
   777→  font-weight: 500;
   778→  margin-top: 4px;
   779→  cursor: pointer;
   780→  user-select: none;
   781→}
   782→
   783→.toggle-switch {
   784→  position: relative;
   785→  flex-shrink: 0;
   786→}
   787→
   788→.toggle-switch input[type="checkbox"] {
   789→  /* visually hidden but accessible */
   790→  position: absolute;
   791→  opacity: 0;
   792→  width: 0;
   793→  height: 0;
   794→}
   795→
   796→.toggle-track {
   797→  display: block;
   798→  width: 44px;
   799→  height: 26px;
   800→  background: var(--surface);
   801→  border: 1px solid var(--border);
   802→  border-radius: 13px;
   803→  position: relative;
   804→  transition: background var(--transition), border-color var(--transition);
   805→  cursor: pointer;
   806→}
   807→
   808→.toggle-track::after {
   809→  content: '';
   810→  position: absolute;
   811→  top: 3px;
   812→  left: 3px;
   813→  width: 18px;
   814→  height: 18px;
   815→  border-radius: 50%;
   816→  background: var(--text-muted);
   817→  transition: transform var(--transition), background var(--transition);
   818→}
   819→
   820→.toggle-switch input:checked + .toggle-track {
   821→  background: rgba(52, 199, 89, 0.25);
   822→  border-color: #34c759;
   823→}
   824→
   825→.toggle-switch input:checked + .toggle-track::after {
   826→  transform: translateX(18px);
   827→  background: #34c759;
   828→}
   829→
   830→.toggle-switch input:focus-visible + .toggle-track {
   831→  outline: 2px solid var(--accent);
   832→  outline-offset: 2px;
   833→}
   834→
   835→/* ===== Touch target minimums (≥ 44px) ===== */
   836→.btn-ghost,
