   863→  font-weight: 600;
   864→  font-family: inherit;
   865→  cursor: pointer;
   866→  transition: all var(--transition);
   867→  letter-spacing: 0.02em;
   868→}
   869→
   870→.btn-readability {
   871→  background: rgba(0, 180, 216, 0.12);
