   172→/* ===== MESSAGE HISTORY ===== */
   173→function addMessage(text, timestamp, status) {
   174→    messagesEmpty.style.display = 'none';
   175→    const el = document.createElement('div');
   176→    el.className = `message ${status}`;
   177→    const timeStr = new Date(timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
   178→    const statusLabel = { sending: 'Sending…', sent: 'Sent', error: 'Failed', 'no-webhook': 'No webhook' };
   179→    el.innerHTML = `
   180→        <p class="message-text">${escapeHtml(text)}</p>
   181→        <div class="message-meta">
   182→            <span class="message-time">${timeStr}</span>
   183→            <span class="message-status">${statusLabel[status] || status}</span>
   184→        </div>
   185→    `;
   186→    messagesEl.appendChild(el);
   187→    el.scrollIntoView({ behavior: 'smooth', block: 'end' });
   188→    return el;
   189→}
