   191→function updateMessageStatus(el, status) {
   192→    el.className = `message ${status}`;
   193→    const statusEl = el.querySelector('.message-status');
   194→    const labels = { sent: 'Sent', error: 'Failed', 'no-webhook': 'No webhook set' };
   195→    if (statusEl) statusEl.textContent = labels[status] || status;
   196→}
