   198→/* ===== WEBHOOK SEND ===== */
   199→async function sendMessage(text, source) {
   200→    const webhookUrl = localStorage.getItem('webhookUrl') || '';
   201→    const timestamp  = new Date().toISOString();
   202→    const payload    = { text, source, timestamp };
   203→    const msgEl      = addMessage(text, timestamp, 'sending');
   204→
   205→    if (!webhookUrl) {
   206→        updateMessageStatus(msgEl, 'no-webhook');
   207→        return;
   208→    }
   209→
   210→    try {
   211→        const res = await fetch(webhookUrl, {
   212→            method:  'POST',
   213→            headers: { 'Content-Type': 'application/json' },
   214→            body:    JSON.stringify(payload),
   215→        });
   216→        if (!res.ok) throw new Error(`HTTP ${res.status}`);
   217→        updateMessageStatus(msgEl, 'sent');
   218→    } catch (err) {
   219→        console.warn('Webhook error:', err);
   220→        updateMessageStatus(msgEl, 'error');
   221→    }
   222→}
