   238→
   239→function getBackendBaseUrl() {
   240→    const backendUrl = localStorage.getItem('brainwaveBackendUrl') || '';
   241→    if (backendUrl) {
   242→        try {
   243→            const url = new URL(backendUrl);
   244→            return `${url.protocol}//${url.host}`;
   245→        } catch (_) { /* fall through to default */ }
   246→    }
   247→    return `${window.location.protocol}//${window.location.host}`;
   248→}
   249→
   250→let _postprocessedContent = '';
   251→
   252→async function runPostProcess(endpoint, label, activeBtn) {
   253→    const text = transcriptText.textContent.trim();
   254→    if (!text) return;
   255→
   256→    // Reset result area
   257→    _postprocessedContent = '';
   258→    postprocessText.textContent = '';
   259→    postprocessLabel.textContent = label;
   260→    postprocessResultActions.hidden = true;
   261→
   262→    // Disable both buttons; show loading on the active one
   263→    readabilityBtn.disabled = true;
   264→    inspireBtn.disabled = true;
   265→    const origLabel = activeBtn.textContent;
   266→    activeBtn.textContent = 'Processing…';
   267→
   268→    // Show the result area (empty initially so user sees it appeared)
   269→    postprocessResult.hidden = false;
   270→
   271→    try {
   272→        const response = await fetch(`${getBackendBaseUrl()}${endpoint}`, {
   273→            method:  'POST',
   274→            headers: { 'Content-Type': 'application/json' },
   275→            body:    JSON.stringify({ text }),
   276→        });
   277→
   278→        if (!response.ok) throw new Error(`HTTP ${response.status}`);
   279→
   280→        const reader  = response.body.getReader();
   281→        const decoder = new TextDecoder();
   282→
   283→        while (true) {
   284→            const { done, value } = await reader.read();
   285→            if (done) break;
   286→            _postprocessedContent += decoder.decode(value, { stream: true });
   287→            postprocessText.textContent = _postprocessedContent;
   288→        }
   289→
   290→        // Streaming complete — show Send button
   291→        postprocessResultActions.hidden = false;
   292→
   293→    } catch (err) {
   294→        console.error('Post-processing error:', err);
   295→        postprocessText.textContent = 'Error: could not process. Check connection and try again.';
   296→    } finally {
   297→        activeBtn.textContent = origLabel;
   298→        readabilityBtn.disabled = false;
   299→        inspireBtn.disabled = false;
   300→    }
   301→}
