   370→/* ===================================================
   371→   QUICK MODE — Web Speech API
   372→   No WebSocket. No backend. Browser-only.
   373→   =================================================== */
   374→
   375→const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
   376→
   377→function getRecognitionLang() {
   378→    return localStorage.getItem('recognitionLang') || navigator.language || 'en-US';
   379→}
   380→
   381→function initRecognition() {
   382→    if (!SpeechRecognition) return;
   383→
   384→    recognition = new SpeechRecognition();
   385→    recognition.continuous      = true;
   386→    recognition.interimResults  = true;
   387→    recognition.lang            = getRecognitionLang();
   388→    recognition.maxAlternatives = 1;
   389→
   390→    recognition.onstart = () => {
   391→        isListening      = true;
   392→        quickFinalTranscript = '';
   393→        showLiveTranscript('', 'quick');
   394→        quickBtn.classList.add('recording');
   395→        quickRing.classList.add('recording');
   396→        quickBtn.setAttribute('aria-pressed', 'true');
   397→        brainstormBtn.disabled = true;
   398→        replayButton.disabled  = true;
   399→        micHint.textContent = 'Listening… tap Quick to stop';
   400→        micHint.classList.add('active');
   401→        micHint.classList.remove('brainstorm-active', 'processing');
   402→    };
   403→
   404→    recognition.onresult = (event) => {
   405→        let interim = '';
   406→        for (let i = event.resultIndex; i < event.results.length; i++) {
   407→            const result = event.results[i];
   408→            if (result.isFinal) {
   409→                quickFinalTranscript += result[0].transcript + ' ';
   410→            } else {
   411→                interim += result[0].transcript;
   412→            }
   413→        }
   414→        const displayText = (quickFinalTranscript + interim).trim();
   415→        updateLiveText(displayText);
   416→        resetSilenceTimer();
   417→    };
   418→
   419→    recognition.onerror = (event) => {
   420→        if (event.error !== 'no-speech') {
   421→            console.warn('Speech recognition error:', event.error);
   422→        }
   423→        stopQuickMode();
   424→    };
   425→
   426→    recognition.onend = () => {
   427→        // If we didn't stop manually, recognition auto-stopped
   428→        if (isListening) {
   429→            finishQuickRecording();
   430→        }
   431→    };
   432→}
   433→
   434→function resetSilenceTimer() {
   435→    clearTimeout(silenceTimer);
   436→    silenceTimer = setTimeout(() => {
   437→        if (isListening) stopQuickMode();
   438→    }, SILENCE_DELAY);
   439→}
   440→
   441→function startQuickMode() {
   442→    if (isListening || isBrainstormRecording || isBrainstormProcessing || isReplaying) return;
   443→    if (!recognition) {
   444→        alert('Speech recognition is not available in this browser.');
   445→        return;
   446→    }
   447→    hideTranscriptBar();
   448→    // Stop wake word listener if running (can't run both concurrently)
   449→    if (wakeWordListening) stopWakeWordListening();
   450→    try {
   451→        recognition.start();
   452→    } catch (e) {
   453→        console.warn('Could not start recognition:', e);
   454→        initRecognition();
   455→        try { recognition.start(); } catch (_) {}
   456→    }
   457→    resetSilenceTimer();
   458→}
   459→
   460→function stopQuickMode() {
   461→    clearTimeout(silenceTimer);
   462→    // Mark as not listening BEFORE calling recognition.stop() so that
   463→    // recognition.onend doesn't also call finishQuickRecording()
   464→    isListening = false;
   465→    if (recognition) {
   466→        try { recognition.stop(); } catch (_) {}
   467→    }
   468→    finishQuickRecording();
   469→}
   470→
   471→function finishQuickRecording() {
   472→    isListening = false;
   473→    clearTimeout(silenceTimer);
   474→    quickBtn.classList.remove('recording');
   475→    quickRing.classList.remove('recording');
   476→    quickBtn.setAttribute('aria-pressed', 'false');
   477→    brainstormBtn.disabled = false;
   478→    micHint.textContent    = '';
   479→    micHint.classList.remove('active');
   480→    hideLiveTranscript();
   481→    updateReplayButtonState();
   482→
   483→    const text = quickFinalTranscript.trim();
   484→    quickFinalTranscript = '';
   485→    if (text) {
   486→        showTranscriptBar(text, 'quick');
   487→    }
   488→
   489→    // Resume hands-free wake word listening
   490→    if (handsFreeEnabled) {
   491→        setTimeout(startWakeWordListening, 400);
   492→    }
   493→}
   494→
   495→quickBtn.addEventListener('click', () => {
   496→    haptic(50);
   497→    if (isListening) {
   498→        stopQuickMode();
   499→    } else if (!isBrainstormRecording && !isBrainstormProcessing && !isReplaying) {
   500→        startQuickMode();
   501→    }
   502→});
