   504→/* ===================================================
   505→   WAKE WORD DETECTION — always-on "Hey Chill" listener
   506→   =================================================== */
   507→
   508→function matchesWakeWord(text) {
   509→    const t = text.toLowerCase().trim();
   510→    // Fuzzy patterns: "hey chill", "hey chil", "a chill", "hay chill", etc.
   511→    return /\b(hey|hay|a)\s+chil{1,2}\b/.test(t);
   512→}
   513→
   514→function initWakeRecognition() {
   515→    if (!SpeechRecognition) return;
   516→
   517→    wakeRecognition = new SpeechRecognition();
   518→    wakeRecognition.continuous      = true;
   519→    wakeRecognition.interimResults  = true;
   520→    wakeRecognition.lang            = getRecognitionLang();
   521→    wakeRecognition.maxAlternatives = 3;
   522→
   523→    wakeRecognition.onresult = (event) => {
   524→        for (let i = event.resultIndex; i < event.results.length; i++) {
   525→            const result = event.results[i];
   526→            for (let j = 0; j < result.length; j++) {
   527→                if (matchesWakeWord(result[j].transcript)) {
   528→                    handleWakeWordDetected();
   529→                    return;
   530→                }
   531→            }
   532→        }
   533→    };
   534→
   535→    wakeRecognition.onerror = (event) => {
   536→        if (event.error === 'not-allowed' || event.error === 'service-not-allowed') {
   537→            console.warn('Wake word mic denied:', event.error);
   538→            wakeWordListening = false;
   539→            updateWakeDot();
   540→            return;
   541→        }
   542→        // Transient error — will be restarted by onend handler
   543→    };
   544→
   545→    wakeRecognition.onend = () => {
   546→        wakeWordListening = false;
   547→        updateWakeDot();
   548→        // Auto-restart when not in an active mode
   549→        if (handsFreeEnabled && !isListening && !isBrainstormRecording && !isBrainstormProcessing) {
   550→            setTimeout(startWakeWordListening, 300);
   551→        }
   552→    };
   553→}
   554→
   555→function startWakeWordListening() {
   556→    if (!SpeechRecognition || !handsFreeEnabled) return;
   557→    if (isListening || isBrainstormRecording || isBrainstormProcessing) return;
   558→    if (wakeWordListening) return;
   559→
   560→    if (!wakeRecognition) initWakeRecognition();
   561→
   562→    try {
   563→        wakeRecognition.start();
   564→        wakeWordListening = true;
   565→        updateWakeDot();
   566→    } catch (e) {
   567→        console.warn('Could not start wake recognition:', e);
   568→        wakeWordListening = false;
   569→        // Re-init and try once more next cycle
   570→        initWakeRecognition();
   571→    }
   572→}
   573→
   574→function stopWakeWordListening() {
   575→    wakeWordListening = false;
   576→    updateWakeDot();
   577→    if (wakeRecognition) {
   578→        try { wakeRecognition.stop(); } catch (_) {}
   579→    }
   580→}
   581→
   582→function handleWakeWordDetected() {
   583→    stopWakeWordListening();
   584→    if (!isListening && !isBrainstormRecording && !isBrainstormProcessing && !isReplaying) {
   585→        haptic(50);
   586→        startQuickMode();
   587→    }
   588→}
   589→
   590→function updateWakeDot() {
   591→    if (!wakeDot) return;
   592→    wakeDot.hidden = !(handsFreeEnabled && wakeWordListening);
   593→}
   594→
   595→function setHandsFree(enabled) {
   596→    handsFreeEnabled = enabled;
   597→    localStorage.setItem('handsFreeEnabled', enabled ? '1' : '0');
   598→    if (enabled) {
   599→        startWakeWordListening();
   600→    } else {
   601→        stopWakeWordListening();
   602→    }
   603→    updateWakeDot();
   604→}
