   606→/* ===================================================
   607→   BRAINSTORM MODE — WebSocket + PCM16 audio streaming
   608→   =================================================== */
   609→
   610→function getWebSocketUrl() {
   611→    const backendUrl = localStorage.getItem('brainwaveBackendUrl') || '';
   612→    if (backendUrl) {
   613→        try {
   614→            const url    = new URL(backendUrl);
   615→            const wsProto = url.protocol === 'https:' ? 'wss:' : 'ws:';
   616→            return `${wsProto}//${url.host}/api/v1/ws`;
   617→        } catch (_) { /* fall through to default */ }
   618→    }
   619→    const proto = window.location.protocol === 'https:' ? 'wss' : 'ws';
   620→    return `${proto}://${window.location.host}/api/v1/ws`;
   621→}
   622→
   623→function updateConnectionStatus(status) {
   624→    connectionStatus.className = 'ws-dot';
   625→    switch (status) {
   626→        case 'connected':
   627→            connectionStatus.classList.add('connected');
   628→            connectionStatus.title = 'Connected';
   629→            break;
   630→        case 'connecting':
   631→            connectionStatus.classList.add('connecting');
   632→            connectionStatus.title = 'Connecting…';
   633→            break;
   634→        case 'idle':
   635→            connectionStatus.classList.add('idle');
   636→            connectionStatus.title = 'Ready';
   637→            break;
   638→        default:
   639→            connectionStatus.title = 'Disconnected';
   640→    }
   641→}
   642→
   643→function initializeWebSocket() {
   644→    ws = new WebSocket(getWebSocketUrl());
   645→
   646→    ws.onopen = () => {
   647→        wsConnected = true;
   648→        updateConnectionStatus('idle');
   649→        if (autoStart && !isBrainstormRecording && !isAutoStarted) {
   650→            isAutoStarted = true;
   651→            startBrainstormRecording();
   652→        }
   653→    };
   654→
   655→    ws.onerror = (error) => {
   656→        console.error('WebSocket error:', error);
   657→        updateConnectionStatus('disconnected');
   658→    };
   659→
   660→    ws.onmessage = (event) => {
   661→        const data = JSON.parse(event.data);
   662→        switch (data.type) {
   663→            case 'status':
   664→                updateConnectionStatus(data.status);
   665→                if (data.status === 'idle') {
   666→                    stopTimer();
   667→                    if (_awaitingBrainstormResult) {
   668→                        _awaitingBrainstormResult = false;
   669→                        isBrainstormProcessing    = false;
   670→                        quickBtn.disabled         = false;
   671→                        brainstormBtn.disabled    = false;
   672→                        micHint.textContent       = '';
   673→                        micHint.classList.remove('active', 'brainstorm-active', 'processing');
   674→                        hideLiveTranscript();
   675→                        updateReplayButtonState();
   676→                        const finalText = brainstormTranscript.trim();
   677→                        brainstormTranscript = '';
   678→                        if (finalText) {
   679→                            showTranscriptBar(finalText, 'brainstorm');
   680→                        }
   681→                        // Resume hands-free after brainstorm completes
   682→                        if (handsFreeEnabled) {
   683→                            setTimeout(startWakeWordListening, 400);
   684→                        }
   685→                    }
   686→                }
   687→                break;
   688→
   689→            case 'text':
   690→                if (data.isNewResponse) {
   691→                    brainstormTranscript = data.content;
   692→                } else {
   693→                    brainstormTranscript += data.content;
   694→                }
   695→                if (isBrainstormProcessing) {
   696→                    updateLiveText(brainstormTranscript);
   697→                }
   698→                break;
   699→
   700→            case 'error':
   701→                alert(data.content);
   702→                updateConnectionStatus('idle');
   703→                _awaitingBrainstormResult = false;
   704→                isBrainstormProcessing    = false;
   705→                quickBtn.disabled         = false;
   706→                brainstormBtn.disabled    = false;
   707→                micHint.textContent       = '';
   708→                micHint.classList.remove('active', 'brainstorm-active', 'processing');
   709→                hideLiveTranscript();
   710→                brainstormTranscript = '';
   711→                updateReplayButtonState();
   712→                if (handsFreeEnabled) {
   713→                    setTimeout(startWakeWordListening, 400);
   714→                }
   715→                break;
   716→        }
   717→    };
   718→
   719→    ws.onclose = () => {
   720→        wsConnected            = false;
   721→        isBrainstormRecording  = false;
   722→        isStopping             = false;
   723→        updateConnectionStatus('disconnected');
   724→        brainstormBtn.classList.remove('recording');
   725→        brainstormRing.classList.remove('recording');
   726→        brainstormBtn.setAttribute('aria-pressed', 'false');
   727→        // Reconnect automatically
   728→        setTimeout(initializeWebSocket, 1000);
   729→    };
   730→}
