   732→/* ===== Audio processing ===== */
   733→function createAudioProcessor() {
   734→    processor = audioContext.createScriptProcessor(4096, 1, 1);
   735→    processor.onaudioprocess = async (e) => {
   736→        if (!isBrainstormRecording && !isStopping) return;
   737→
   738→        const inputData = e.inputBuffer.getChannelData(0);
   739→        const pcmData   = new Int16Array(inputData.length);
   740→        for (let i = 0; i < inputData.length; i++) {
   741→            pcmData[i] = Math.max(-32768, Math.min(32767, Math.floor(inputData[i] * 32767)));
   742→        }
   743→
   744→        const combined = new Int16Array(audioBuffer.length + pcmData.length);
   745→        combined.set(audioBuffer);
   746→        combined.set(pcmData, audioBuffer.length);
   747→        audioBuffer = combined;
   748→
   749→        if (audioBuffer.length >= 24000) {
   750→            const sendBuffer = audioBuffer.slice(0, 24000);
   751→            audioBuffer      = audioBuffer.slice(24000);
   752→
   753→            if (ws.readyState === WebSocket.OPEN) {
   754→                ws.send(sendBuffer.buffer);
   755→
   756→                if (storageAvailable && currentSessionId && sessionStartTime) {
   757→                    const deltaMs = performance.now() - sessionStartTime;
   758→                    await appendChunk(currentSessionId, {
   759→                        seq: chunkSeq++, deltaMs,
   760→                        kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
   761→                    });
   762→                }
   763→            }
   764→        }
   765→    };
   766→    return processor;
   767→}
   768→
   769→async function initAudio(audioStream) {
   770→    if (audioContext && audioContext.state !== 'closed') {
   771→        try { await audioContext.close(); } catch (_) {}
   772→    }
   773→    audioContext = new (window.AudioContext || window.webkitAudioContext)();
   774→    source       = audioContext.createMediaStreamSource(audioStream);
   775→    processor    = createAudioProcessor();
   776→    source.connect(processor);
   777→    processor.connect(audioContext.destination);
   778→    if (audioContext.state === 'suspended') await audioContext.resume();
   779→}
   780→
   781→function cleanupAudioResources() {
   782→    if (stream) {
   783→        stream.getTracks().forEach(t => t.stop());
   784→        stream = null;
   785→    }
   786→    if (audioContext && audioContext.state !== 'closed') {
   787→        audioContext.close().catch(() => {});
   788→        audioContext = null;
   789→    }
   790→    source            = null;
   791→    processor         = null;
   792→    streamInitialized = false;
   793→}
   794→
   795→async function startBrainstormRecording() {
   796→    if (isBrainstormRecording || isListening || isBrainstormProcessing || isReplaying) return;
   797→
   798→    if (!ws || ws.readyState !== WebSocket.OPEN) {
   799→        alert('WebSocket is not connected. Please wait or check the backend URL in Settings.');
   800→        return;
   801→    }
   802→
   803→    // Pause wake word listening while brainstorm is active
   804→    if (wakeWordListening) stopWakeWordListening();
   805→
   806→    try {
   807→        brainstormTranscript = '';
   808→        hideTranscriptBar();
   809→
   810→        // Re-use existing stream if still alive, else reinit
   811→        let streamActive = false;
   812→        try {
   813→            streamActive = streamInitialized && stream && stream.active &&
   814→                           stream.getTracks().every(t => t.readyState === 'live');
   815→        } catch (_) { streamActive = false; }
   816→
   817→        if (!streamActive) {
   818→            cleanupAudioResources();
   819→            stream = await navigator.mediaDevices.getUserMedia({
   820→                audio: { channelCount: 1, echoCancellation: true, noiseSuppression: true, autoGainControl: true },
   821→            });
   822→            streamInitialized = true;
   823→        }
   824→
   825→        if (!audioContext || audioContext.state === 'closed') {
   826→            await initAudio(stream);
   827→        } else if (audioContext.state === 'suspended') {
   828→            await audioContext.resume();
   829→        }
   830→
   831→        isBrainstormRecording = true;
   832→        if (storageAvailable) await createSession();
   833→
   834→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
   835→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
   836→
   837→        startTimer();
   838→        brainstormBtn.classList.add('recording');
   839→        brainstormRing.classList.add('recording');
   840→        brainstormBtn.setAttribute('aria-pressed', 'true');
   841→        quickBtn.disabled    = true;
   842→        replayButton.disabled = true;
   843→        micHint.textContent  = 'Recording… tap Brainstorm to stop';
   844→        micHint.classList.add('active', 'brainstorm-active');
   845→        micHint.classList.remove('processing');
   846→        showLiveTranscript('', 'brainstorm');
   847→
   848→    } catch (error) {
   849→        console.error('Error starting Brainstorm:', error);
   850→        isBrainstormRecording = false;
   851→        alert('Error accessing microphone: ' + error.message);
   852→    }
   853→}
   854→
   855→async function stopBrainstormRecording() {
   856→    if (!isBrainstormRecording) return;
   857→
   858→    isStopping            = true;
   859→    isBrainstormRecording = false;
   860→    const durationMs      = sessionStartTime ? performance.now() - sessionStartTime : 0;
   861→
   862→    stopTimer();
   863→    brainstormBtn.classList.remove('recording');
   864→    brainstormRing.classList.remove('recording');
   865→    brainstormBtn.setAttribute('aria-pressed', 'false');
   866→    brainstormBtn.disabled = true; // keep disabled until WS idle
   867→
   868→    micHint.textContent = 'Processing…';
   869→    micHint.classList.remove('brainstorm-active');
   870→    micHint.classList.add('processing');
   871→
   872→    // Allow any in-flight onaudioprocess callbacks to complete
   873→    await new Promise(resolve => setTimeout(resolve, 100));
   874→
   875→    // Flush remaining audio buffer
   876→    if (audioBuffer.length > 0 && ws.readyState === WebSocket.OPEN) {
   877→        const sendBuffer = audioBuffer.slice();
   878→        ws.send(sendBuffer.buffer);
   879→        if (storageAvailable && currentSessionId && sessionStartTime) {
   880→            const deltaMs = performance.now() - sessionStartTime;
   881→            await appendChunk(currentSessionId, {
   882→                seq: chunkSeq++, deltaMs,
   883→                kind: 'audio', payload: sendBuffer.buffer, byteLength: sendBuffer.byteLength,
   884→            });
   885→        }
   886→        audioBuffer = new Int16Array(0);
   887→    }
   888→
   889→    isStopping = false;
   890→
   891→    // Small delay to ensure all audio sent before stop signal
   892→    await new Promise(resolve => setTimeout(resolve, 500));
   893→    ws.send(JSON.stringify({ type: 'stop_recording' }));
   894→
   895→    if (storageAvailable && currentSessionId) {
   896→        await completeSession(currentSessionId, durationMs);
   897→        currentSessionId  = null;
   898→        sessionStartTime  = null;
   899→        chunkSeq          = 0;
   900→    }
   901→
   902→    // Switch to processing state — WS idle handler will finish the flow
   903→    isBrainstormProcessing    = true;
   904→    _awaitingBrainstormResult = true;
   905→    liveText.textContent      = 'Processing…';
   906→    liveText.classList.remove('has-text');
   907→}
   908→
   909→brainstormBtn.addEventListener('click', () => {
   910→    haptic(50);
   911→    if (isBrainstormRecording) {
   912→        stopBrainstormRecording();
   913→    } else if (!isListening && !isBrainstormProcessing && !isReplaying) {
   914→        startBrainstormRecording();
   915→    }
   916→});
