   918→/* ===================================================
   919→   REPLAY — sends stored IndexedDB audio through WS
   920→   =================================================== */
   921→
   922→async function replayLastRecording() {
   923→    if (isBrainstormRecording || isReplaying || isListening || isBrainstormProcessing) return;
   924→
   925→    const session = await getLatestCompletedSession();
   926→    if (!session) {
   927→        alert('No completed recording found to replay.');
   928→        return;
   929→    }
   930→
   931→    isReplaying              = true;
   932→    quickBtn.disabled        = true;
   933→    brainstormBtn.disabled   = true;
   934→    replayButton.disabled    = true;
   935→    replayButton.classList.add('replaying');
   936→    brainstormTranscript     = '';
   937→
   938→    try {
   939→        hideTranscriptBar();
   940→        const chunks = await getSessionChunks(session.id);
   941→        if (chunks.length === 0) throw new Error('No audio chunks found for session');
   942→
   943→        // Wait for WS if needed
   944→        if (!wsConnected || ws.readyState !== WebSocket.OPEN) {
   945→            await new Promise(resolve => {
   946→                const check = setInterval(() => {
   947→                    if (wsConnected && ws.readyState === WebSocket.OPEN) { clearInterval(check); resolve(); }
   948→                }, 100);
   949→            });
   950→        }
   951→
   952→        const selectedModel = modelSelect ? modelSelect.value : 'gpt-realtime-mini-2025-12-15';
   953→        ws.send(JSON.stringify({ type: 'start_recording', model: selectedModel }));
   954→        await new Promise(resolve => setTimeout(resolve, 200));
   955→
   956→        for (const chunk of chunks.filter(c => c.kind === 'audio' && c.payload)) {
   957→            if (ws.readyState === WebSocket.OPEN) {
   958→                ws.send(chunk.payload);
   959→            } else {
   960→                throw new Error('WebSocket closed during replay');
   961→            }
   962→        }
   963→
   964→        ws.send(JSON.stringify({ type: 'stop_recording' }));
   965→
   966→        isBrainstormProcessing    = true;
   967→        _awaitingBrainstormResult = true;
   968→        micHint.textContent       = 'Processing replay…';
   969→        micHint.classList.add('active', 'processing');
   970→        micHint.classList.remove('brainstorm-active');
   971→        showLiveTranscript('Processing replay…', 'brainstorm');
   972→
   973→    } catch (error) {
   974→        console.error('Replay error:', error);
   975→        alert('Error replaying recording: ' + error.message);
   976→        isBrainstormProcessing    = false;
   977→        _awaitingBrainstormResult = false;
   978→        micHint.textContent       = '';
   979→        micHint.classList.remove('active', 'processing');
   980→        quickBtn.disabled        = false;
   981→        brainstormBtn.disabled   = false;
   982→    } finally {
   983→        isReplaying = false;
   984→        replayButton.classList.remove('replaying');
   985→        updateReplayButtonState();
   986→        // quickBtn/brainstormBtn re-enabled by WS idle handler if processing started
   987→        if (!isBrainstormProcessing) {
   988→            quickBtn.disabled      = false;
   989→            brainstormBtn.disabled = false;
   990→        }
   991→    }
   992→}
   993→
   994→replayButton.onclick = replayLastRecording;
