   996→function updateReplayButtonState() {
   997→    if (!replayButton) return;
   998→
   999→    if (!storageAvailable) {
  1000→        replayButton.disabled = true;
  1001→        replayButton.title    = 'Local storage not available';
  1002→        return;
  1003→    }
  1004→    if (isBrainstormRecording || isReplaying || isListening || isBrainstormProcessing) {
  1005→        replayButton.disabled = true;
