  1018→/* ===================================================
  1019→   INDEXEDDB — stores PCM16 chunks for replay
  1020→   =================================================== */
  1021→
  1022→function createDBStores(event) {
  1023→    const d = event.target.result;
  1024→    if (!d.objectStoreNames.contains('sessions')) {
  1025→        const s = d.createObjectStore('sessions', { keyPath: 'id', autoIncrement: true });
  1026→        s.createIndex('status',    'status',    { unique: false });
  1027→        s.createIndex('createdAt', 'createdAt', { unique: false });
  1028→    }
  1029→    if (!d.objectStoreNames.contains('chunks')) {
  1030→        const c = d.createObjectStore('chunks', { keyPath: 'id', autoIncrement: true });
  1031→        c.createIndex('sessionId', 'sessionId', { unique: false });
  1032→        c.createIndex('seq',       'seq',       { unique: false });
  1033→    }
  1034→}
  1035→
  1036→async function initIndexedDB() {
  1037→    return new Promise((resolve) => {
  1038→        const request = indexedDB.open('brainwave-replay', 1);
  1039→
  1040→        request.onerror = () => {
  1041→            console.warn('IndexedDB not available, replay disabled');
  1042→            storageAvailable = false;
  1043→            resolve(false);
  1044→        };
  1045→
  1046→        request.onsuccess = () => {
  1047→            db = request.result;
  1048→            if (!db.objectStoreNames.contains('sessions') || !db.objectStoreNames.contains('chunks')) {
  1049→                db.close();
  1050→                const del = indexedDB.deleteDatabase('brainwave-replay');
  1051→                del.onsuccess = () => {
  1052→                    const reopen = indexedDB.open('brainwave-replay', 1);
  1053→                    reopen.onsuccess       = () => { db = reopen.result; storageAvailable = true; updateReplayButtonState(); resolve(true); };
  1054→                    reopen.onerror         = () => { storageAvailable = false; resolve(false); };
  1055→                    reopen.onupgradeneeded = createDBStores;
  1056→                };
  1057→                del.onerror = () => { storageAvailable = false; resolve(false); };
  1058→                return;
  1059→            }
  1060→            storageAvailable = true;
  1061→            updateReplayButtonState();
  1062→            resolve(true);
  1063→        };
  1064→
  1065→        request.onupgradeneeded = createDBStores;
  1066→    });
  1067→}
  1068→
  1069→async function createSession() {
  1070→    if (!db) return null;
  1071→    return new Promise((resolve, reject) => {
  1072→        const tx    = db.transaction(['sessions'], 'readwrite');
  1073→        const store = tx.objectStore('sessions');
  1074→        const req   = store.add({ createdAt: new Date(), status: 'recording', sampleRate: 24000, channelCount: 1, durationMs: 0 });
  1075→        req.onsuccess = () => {
  1076→            currentSessionId  = req.result;
  1077→            sessionStartTime  = performance.now();
  1078→            chunkSeq          = 0;
  1079→            appendChunk(currentSessionId, { seq: 0, deltaMs: 0, kind: 'start', payload: null, byteLength: 0 });
  1080→            resolve(currentSessionId);
  1081→        };
  1082→        req.onerror = () => reject(req.error);
  1083→    });
  1084→}
  1085→
  1086→async function appendChunk(sessionId, chunk) {
  1087→    if (!db || !sessionId) return;
  1088→    return new Promise((resolve) => {
  1089→        const tx    = db.transaction(['chunks'], 'readwrite');
  1090→        const store = tx.objectStore('chunks');
  1091→        const req   = store.add({ sessionId, seq: chunk.seq, deltaMs: chunk.deltaMs, kind: chunk.kind, payload: chunk.payload, byteLength: chunk.byteLength });
  1092→        req.onsuccess = () => resolve();
  1093→        req.onerror   = () => resolve(); // don't fail recording on storage error
  1094→    });
  1095→}
  1096→
  1097→async function completeSession(sessionId, durationMs) {
  1098→    if (!db || !sessionId) return;
  1099→    return new Promise((resolve) => {
  1100→        const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1101→        const sessionsStore = tx.objectStore('sessions');
  1102→        const chunksStore   = tx.objectStore('chunks');
  1103→        const req           = sessionsStore.get(sessionId);
  1104→        req.onsuccess = () => {
  1105→            const sess = req.result;
  1106→            sess.status    = 'completed';
  1107→            sess.durationMs = durationMs;
  1108→            sessionsStore.put(sess);
  1109→            chunksStore.add({ sessionId, seq: chunkSeq++, deltaMs: durationMs, kind: 'stop', payload: null, byteLength: 0 });
  1110→            enforceQuota({ maxSessions: 5 });
  1111→            resolve();
  1112→        };
  1113→        req.onerror = () => resolve();
  1114→    });
  1115→}
  1116→
  1117→async function enforceQuota({ maxSessions }) {
  1118→    if (!db) return;
  1119→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1120→    const sessionsStore = tx.objectStore('sessions');
  1121→    const sessions      = [];
  1122→    sessionsStore.index('createdAt').openCursor().onsuccess = (event) => {
  1123→        const cursor = event.target.result;
  1124→        if (cursor) { sessions.push(cursor.value); cursor.continue(); }
  1125→        else {
  1126→            sessions.sort((a, b) => a.createdAt - b.createdAt);
  1127→            while (sessions.length > maxSessions) deleteSession(sessions.shift().id);
  1128→        }
  1129→    };
  1130→}
  1131→
  1132→async function deleteSession(sessionId) {
  1133→    if (!db) return;
  1134→    const tx            = db.transaction(['sessions', 'chunks'], 'readwrite');
  1135→    const sessionsStore = tx.objectStore('sessions');
  1136→    const chunksStore   = tx.objectStore('chunks');
  1137→    chunksStore.index('sessionId').openKeyCursor(IDBKeyRange.only(sessionId)).onsuccess = (event) => {
  1138→        const cursor = event.target.result;
  1139→        if (cursor) { chunksStore.delete(cursor.primaryKey); cursor.continue(); }
  1140→    };
  1141→    sessionsStore.delete(sessionId);
  1142→}
  1143→
  1144→async function getLatestCompletedSession() {
  1145→    if (!db) return null;
  1146→    return new Promise((resolve) => {
  1147→        const tx    = db.transaction(['sessions'], 'readonly');
  1148→        const req   = tx.objectStore('sessions').index('status').getAll('completed');
  1149→        req.onsuccess = () => {
  1150→            const sessions = req.result;
  1151→            if (!sessions.length) { resolve(null); return; }
  1152→            sessions.sort((a, b) => b.createdAt - a.createdAt);
  1153→            resolve(sessions[0]);
  1154→        };
  1155→        req.onerror = () => resolve(null);
  1156→    });
  1157→}
  1158→
  1159→async function getSessionChunks(sessionId) {
  1160→    if (!db || !sessionId) return [];
  1161→    return new Promise((resolve) => {
  1162→        const tx  = db.transaction(['chunks'], 'readonly');
  1163→        const req = tx.objectStore('chunks').index('sessionId').getAll(sessionId);
  1164→        req.onsuccess = () => {
  1165→            const chunks = req.result;
  1166→            chunks.sort((a, b) => a.seq - b.seq);
